const inputData = $('Translate Input (Sarvam)').first().json || {};
const modelResponse = $input.first().json || {};

function asString(v) {
  return v == null ? '' : String(v);
}

function parseModelProfile(resp) {
  try {
    const content = resp?.choices?.[0]?.message?.content;
    if (!content) return null;
    const cleaned = asString(content)
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/```$/i, '')
      .trim();
    const parsed = JSON.parse(cleaned);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (e) {
    return null;
  }
}

function detectStateCode(text) {
  const t = asString(text).toLowerCase();
  const map = {
    'karnataka': 'KA',
    'tamil nadu': 'TN',
    'tamilnadu': 'TN',
    'maharashtra': 'MH',
    'uttar pradesh': 'UP',
    'rajasthan': 'RJ',
    'kerala': 'KL',
    'andhra pradesh': 'AP',
    'telangana': 'TG',
    'delhi': 'DL',
  };
  for (const [k, v] of Object.entries(map)) {
    if (t.includes(k)) return v;
  }
  return null;
}

function fallbackExtract(rawText) {
  const text = asString(rawText);
  const lower = text.toLowerCase();
  const p = {};

  const nameMatch = text.match(/my name is\s+([a-zA-Z .'-]{2,60})/i) || text.match(/i am\s+([a-zA-Z .'-]{2,60})/i);
  if (nameMatch) p.name = asString(nameMatch[1]).trim();

  const ageMatch = text.match(/(\d{1,3})\s*(?:years?|yrs?|year old|y\/o)/i);
  if (ageMatch) p.age = parseInt(ageMatch[1], 10);

  const incomeMatch =
    text.match(/monthly income(?: is)?\s*(?:rs\.?|₹)?\s*([0-9,]+)/i) ||
    text.match(/earn(?:ing|ings)?(?: is)?\s*(?:rs\.?|₹)?\s*([0-9,]+)/i) ||
    text.match(/income(?: is)?\s*(?:rs\.?|₹)?\s*([0-9,]+)/i);
  if (incomeMatch) p.monthly_income = parseInt(incomeMatch[1].replace(/,/g, ''), 10);

  const addrMatch = text.match(/(?:live at|address is|from)\s+([^.;]+)/i);
  if (addrMatch) p.address = asString(addrMatch[1]).trim();

  if (lower.includes('female')) p.gender = 'female';
  else if (lower.includes('male')) p.gender = 'male';

  if (lower.includes('widow') || lower.includes('widowed')) p.marital_status = 'widowed';
  else if (lower.includes('married')) p.marital_status = 'married';
  else if (lower.includes('single')) p.marital_status = 'single';

  const districtMatch = text.match(/\b(mysuru|mysore|chennai|coimbatore|bengaluru|bangalore|jaipur|pune|mumbai|lucknow)\b/i);
  if (districtMatch) p.district = districtMatch[1];

  const stateCode = detectStateCode(text);
  if (stateCode) p.state_code = stateCode;

  if (/\bunemploy(ed|ment)?\b/i.test(text)) p.occupation = 'unemployed';
  else if (/\bfarmer\b/i.test(text)) p.occupation = 'farmer';
  else if (/\blabou?r\b/i.test(text)) p.occupation = 'labour';

  const disPct = text.match(/(\d{1,3})\s*%/);
  if (/\bdisab/i.test(text)) p.disability_status = true;
  if (disPct) p.disability_percentage = parseInt(disPct[1], 10);

  return p;
}

function mergeProfile(modelProfile, fallbackProfile) {
  const model = modelProfile && typeof modelProfile === 'object' ? modelProfile : {};
  const fb = fallbackProfile && typeof fallbackProfile === 'object' ? fallbackProfile : {};
  const pick = (...vals) => vals.find((v) => v !== undefined && v !== null && String(v).trim() !== '');

  const monthlyIncome = Number(pick(model.monthly_income, fb.monthly_income));

  return {
    name: pick(model.name, fb.name, model.applicant_name, fb.applicant_name) || null,
    age: Number.isFinite(Number(pick(model.age, fb.age))) ? Number(pick(model.age, fb.age)) : null,
    gender: pick(model.gender, fb.gender) || 'not_specified',
    district: pick(model.district, fb.district) || null,
    address: pick(model.address, fb.address) || null,
    monthly_income: Number.isFinite(monthlyIncome) ? monthlyIncome : null,
    annual_income: Number.isFinite(Number(pick(model.annual_income, fb.annual_income)))
      ? Number(pick(model.annual_income, fb.annual_income))
      : (Number.isFinite(monthlyIncome) ? monthlyIncome * 12 : null),
    marital_status: pick(model.marital_status, fb.marital_status) || 'not_specified',
    state_code: pick(model.state_code, fb.state_code, detectStateCode(inputData.translated_text || inputData.original_text || '')) || 'ALL',
    occupation: pick(model.occupation, fb.occupation) || 'not_specified',
    disability_status: Boolean(pick(model.disability_status, fb.disability_status)),
    disability_percentage: Number.isFinite(Number(pick(model.disability_percentage, fb.disability_percentage)))
      ? Number(pick(model.disability_percentage, fb.disability_percentage))
      : 0,
  };
}

const modelProfile = parseModelProfile(modelResponse);
const transcriptText =
  inputData.translated_text ||
  inputData.original_text ||
  (Array.isArray(inputData.messages) ? inputData.messages.filter((m) => m.role === 'user').map((m) => m.text).join(' ') : '');
const fallbackProfile = fallbackExtract(transcriptText);
const profile = mergeProfile(modelProfile, fallbackProfile);

const phoneNumber = inputData.customer_number || '+910000000000';
const hashInput = phoneNumber + '_zelia_salt_2026';
let hash = 5381;
for (let i = 0; i < hashInput.length; i++) {
  hash = ((hash << 5) + hash) + hashInput.charCodeAt(i);
  hash = hash & hash;
}
const householdIdHash = Math.abs(hash).toString(16).padStart(16, '0');

return {
  json: {
    call_id: inputData.call_id || `call_${Date.now()}`,
    phone_number: inputData.customer_number,
    household_id_hash: householdIdHash,
    original_language: inputData.original_language || 'en',
    sarvam_lang_code: inputData.sarvam_lang_code || null,
    raw_query: transcriptText,
    original_text: inputData.original_text || null,
    user_profile: {
      name: profile.name,
      applicant_name: profile.name,
      age: profile.age,
      gender: profile.gender,
      district: profile.district,
      address: profile.address,
      monthly_income: profile.monthly_income,
      annual_income: profile.annual_income,
      marital_status: profile.marital_status,
      state_code: profile.state_code,
      occupation: profile.occupation,
      disability_status: profile.disability_status,
      disability_percentage: profile.disability_percentage
    },
    paralinguistic: {
      confidence: inputData.metadata?.confidence || 0.5,
      tone: inputData.metadata?.tone || 'neutral',
      urgency: inputData.metadata?.urgency || 'normal',
      location: inputData.metadata?.location || null
    },
    profile_source: modelProfile ? 'groq' : 'fallback_regex',
    extraction_timestamp: new Date().toISOString()
  }
};

// Build eligibility response with normalized template mapping contract
const callData = $('Parse Profile + Hash').first().json;
const rawSchemes = $input.all().map(item => item.json);

if (rawSchemes.length === 0) {
  return {
    json: {
      call_id: callData.call_id,
      status: 'no_eligible_schemes',
      message: 'Unfortunately, you do not currently qualify for any government schemes based on your profile.',
      user_profile: callData.user_profile,
      eligible_schemes: []
    }
  };
}

function normalizeRequiredDocs(value) {
  if (Array.isArray(value)) {
    return value.map((x) => String(x).trim()).filter((x) => x && x !== '[]' && x !== '{}');
  }
  if (typeof value === 'string') {
    const t = value.trim();
    if (!t || t === '[]' || t === '{}') return [];
    if (t.startsWith('[') && t.endsWith(']')) {
      try {
        const parsed = JSON.parse(t);
        if (Array.isArray(parsed)) return parsed.map((x) => String(x).trim()).filter(Boolean);
      } catch (e) {}
    }
    return t.split(',').map((x) => x.trim()).filter((x) => x && x !== '[]' && x !== '{}');
  }
  return [];
}

const schemeTemplateFallback = {
  'ka-widow-pension': 'pension1.pdf',
  'ka-old-age-pension': 'pension1.pdf',
  'ka-disability-pension': 'disabledgovt.pdf',
  'ka-destitute-pension': 'intimationform.pdf',
  'pmjay': 'Application_for_assiatance.pdf',
  'pm-kisan': 'jobskilltraining.pdf',
  'pm-ujjwala': 'swasraya.pdf',
  'nsap-ignoaps': 'niramaya.pdf'
};

const schemes = rawSchemes.map((s) => {
  const schemeId = s.scheme_id || s.id || null;
  const templateKey = s.pdf_template_key || (schemeId ? schemeTemplateFallback[schemeId] : null) || null;
  return {
    ...s,
    scheme_id: schemeId,
    scheme_name: s.scheme_name || s.title || s.name || 'Unknown Scheme',
    pdf_template_key: templateKey,
    required_documents: normalizeRequiredDocs(s.required_documents),
    benefits: s.benefits || s.benefit || ''
  };
});

const rankedSchemes = [...schemes].sort((a, b) => Number(b.eligibility_score || 0) - Number(a.eligibility_score || 0));
let primary = rankedSchemes[0] || {};

// Ensure template key is always available for PDF stage.
if (primary && !primary.pdf_template_key) {
  primary.pdf_template_key = schemeTemplateFallback[primary.scheme_id] || 'Application_for_assiatance.pdf';
}

const safeSchemes = rankedSchemes.map((s) => ({
  ...s,
  pdf_template_key: s.pdf_template_key || schemeTemplateFallback[s.scheme_id] || 'Application_for_assiatance.pdf',
}));

// Compute monthly benefits when numeric values are available in benefit text
const totalMonthlyBenefit = schemes.reduce((sum, s) => {
  const txt = String(s.benefits || '');
  const m = txt.match(/(?:Rs\.?|₹)\s*([0-9,]+)/i);
  if (!m) return sum;
  const val = parseInt(m[1].replace(/,/g, ''), 10);
  return Number.isFinite(val) ? sum + val : sum;
}, 0);

return {
  json: {
    call_id: callData.call_id,
    user_profile: callData.user_profile,
    eligible_schemes: safeSchemes,
    scheme_id: primary.scheme_id || null,
    scheme_name: primary.scheme_name || null,
    pdf_template_key: primary.pdf_template_key || null,
    required_documents: primary.required_documents || [],
    benefits: primary.benefits || '',
    eligible_count: safeSchemes.length,
    total_monthly_benefit: totalMonthlyBenefit,
    status: 'schemes_found'
  }
};

// Generate natural language response
const data = $input.first().json;

if (data.status === 'no_eligible_schemes') {
  return {
    json: {
      ...data,
      response_text: data.message,
      response_type: 'no_match'
    }
  };
}

const schemes = data.eligible_schemes;
let response = '';

if (schemes.length === 1) {
  const s = schemes[0];
  response = `Good news! You are eligible for ${s.scheme_name}. This scheme provides ${s.benefits}. To apply, please visit your nearest Seva Sindhu kendra with the required documents.`;
} else {
  response = `Excellent news! Based on your profile, you are eligible for ${schemes.length} government schemes:\n\n`;

  schemes.forEach((s, i) => {
    response += `${i + 1}. ${s.scheme_name}\n`;
    response += `   Benefits: ${s.benefits}\n`;
    if (s.description) {
      response += `   Details: ${s.description.substring(0, 100)}...\n`;
    }
    response += `\n`;
  });

  if (data.total_monthly_benefit > 0) {
    response += `Total monthly benefits: Rs.${data.total_monthly_benefit.toLocaleString()}\n\n`;
  }

  response += `To apply for these schemes, please visit your nearest Seva Sindhu kendra or government office with your Aadhar card, income certificate, and other required documents.`;
}

return {
  json: {
    ...data,
    response_text: response,
    response_type: 'success'
  }
};

// Record Verbal Consent with paralinguistic verification
const data = $input.first().json;
const profile = $('Parse Profile + Hash').first().json;

const consentLedger = {
  timestamp: new Date().toISOString(),
  consent_verified: profile.paralinguistic.confidence >= 0.6,
