    original_language: profile.original_language,
    original_text: profile.original_text,
    consent_ledger: consentLedger,
    consent_recorded: consentLedger.consent_verified
  }
};

const data = $input.first().json;
const language = data.original_language || 'en';

// For non-English, add a note about native language response
let responseNative = data.response_text;
if (language === 'hi') {
    responseNative = '(Hindi translation will be provided via Sarvam AI) ' + data.response_text;
} else if (language === 'ta') {
    responseNative = '(Tamil translation will be provided via Sarvam AI) ' + data.response_text;
} else if (language !== 'en') {
    responseNative = '(Translation to ' + language + ' via Sarvam AI) ' + data.response_text;
}

return {
    json: {
          ...data,
          response_native: responseNative,
          response_english: data.response_text,
          call_id: data.call_id,
          eligible_schemes: data.eligible_schemes
    }
}

// Fill ORIGINAL government template pages only (no appended summary page).
