const storagePrefix = householdHash || callId;
const templateKey = data.pdf_template_key || (schemes[0] && schemes[0].pdf_template_key) || schemeTemplateMap[schemeIdRaw] || schemeTemplateMap[schemeId] || null;
if (!templateKey) {
